import plant
from pid import PID

def metrics(kp, ki, kd):
    c = PID(kp, ki, kd, 0.01); v=0.0; vs=[]
    for k in range(6001):
        u=c.update(25.0,v); vs.append(v)
        if k<6000: v=plant.rk4_step(v,u,0.01)
    over=(max(vs)-25)/25*100
    out=[i for i,x in enumerate(vs) if abs(x-25)>0.5]
    ts=(out[-1]+1)*0.01 if out else 0.0
    return over, ts, vs[-1]-25

best=[]
for kp in [300,500,800,1000,1400]:
    for ki in [200,400,700,972,1300]:
        for kd in [600,900,1100,1300,1600]:
            o,t,e = metrics(kp,ki,kd)
            if o<4 and t<10 and abs(e)<0.05:
                best.append((round(o,2), round(t,2), kp,ki,kd))
best.sort(key=lambda x:x[1])
for b in best[:12]: print(b)
EOF")

